examples.code:
server_name="shop.local"
port=8080
root="/srv/shop/current"

cat > site.conf <<EOF
server {
    listen $port;
    server_name $server_name;
    root $root;

    location / {
        try_files \$uri \$uri/ /index.html;
    }
}
EOF

cat site.conf

examples.output:
server {
    listen 8080;
    server_name shop.local;
    root /srv/shop/current;

    location / {
